create table if not exists public.caleris_xp_ledger(id uuid primary key default gen_random_uuid(),member_id uuid not null references public.members(id) on delete cascade,amount integer not null check(amount>0),source_type text not null check(source_type in('race_result','checkin','quest','milestone','shop_purchase','admin_adjustment')),source_id text not null,description text not null default '',created_at timestamptz not null default now(),unique(member_id,source_type,source_id));
create index if not exists caleris_xp_ledger_member_created_idx on public.caleris_xp_ledger(member_id,created_at desc);
create table if not exists public.caleris_milestone_definitions(id uuid primary key default gen_random_uuid(),scope text not null check(scope in('driver','team')),code text not null unique,title text not null,description text not null default '',metric_key text not null,target_value numeric not null check(target_value>0),xp_reward integer not null default 0,badge_code text,active boolean not null default true);
create table if not exists public.caleris_milestone_progress(id uuid primary key default gen_random_uuid(),milestone_id uuid not null references public.caleris_milestone_definitions(id) on delete cascade,scope text not null check(scope in('driver','team')),member_id uuid references public.members(id) on delete cascade,team_id uuid references public.teams(id) on delete cascade,current_value numeric not null default 0,completed_at timestamptz,updated_at timestamptz not null default now(),check((scope='driver' and member_id is not null and team_id is null) or (scope='team' and team_id is not null and member_id is null)),unique(milestone_id,member_id),unique(milestone_id,team_id));
create table if not exists public.caleris_activity_feed(id uuid primary key default gen_random_uuid(),actor_member_id uuid references public.members(id) on delete set null,team_id uuid references public.teams(id) on delete set null,event_type text not null,title text not null,body text not null default '',metadata jsonb not null default '{}'::jsonb,visibility text not null default 'community' check(visibility in('community','team','private')),created_at timestamptz not null default now());
create index if not exists caleris_activity_feed_created_idx on public.caleris_activity_feed(created_at desc);
create table if not exists public.caleris_community_polls(id uuid primary key default gen_random_uuid(),title text not null,description text not null default '',poll_type text not null check(poll_type in('driver_of_period','team_of_period','driver_of_season','team_of_season','fia_nomination')),status text not null default 'draft' check(status in('draft','open','closed','published')),starts_at timestamptz not null default now(),ends_at timestamptz not null,season_id uuid references public.license_seasons(id) on delete set null,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),check(ends_at>starts_at));
create table if not exists public.caleris_community_poll_options(id uuid primary key default gen_random_uuid(),poll_id uuid not null references public.caleris_community_polls(id) on delete cascade,member_id uuid references public.members(id) on delete cascade,team_id uuid references public.teams(id) on delete cascade,label text not null,check((member_id is not null)::int+(team_id is not null)::int=1),unique(poll_id,member_id),unique(poll_id,team_id));
create table if not exists public.caleris_community_votes(id uuid primary key default gen_random_uuid(),poll_id uuid not null references public.caleris_community_polls(id) on delete cascade,voter_member_id uuid not null references public.members(id) on delete cascade,option_id uuid not null references public.caleris_community_poll_options(id) on delete cascade,created_at timestamptz not null default now(),unique(poll_id,voter_member_id));
create table if not exists public.caleris_digital_id_cards(member_id uuid primary key references public.members(id) on delete cascade,theme text not null default 'classic' check(theme in('classic','premio','zwei','gold')),accent_color text not null default '#b99752' check(accent_color ~ '^#[0-9A-Fa-f]{6}$'),tagline text not null default '',public_visible boolean not null default true,updated_at timestamptz not null default now());
create table if not exists public.caleris_season_yearbooks(id uuid primary key default gen_random_uuid(),season_id uuid not null references public.license_seasons(id) on delete cascade,title text not null,content jsonb not null default '{}'::jsonb,status text not null default 'draft' check(status in('draft','published')),generated_at timestamptz not null default now(),generated_by uuid references auth.users(id) on delete set null,unique(season_id));
create table if not exists public.caleris_achievement_badges(code text primary key,title text not null,description text not null default '',icon text not null default 'award',rarity text not null default 'common' check(rarity in('common','rare','epic','legendary')),active boolean not null default true);
create table if not exists public.caleris_member_badges(member_id uuid not null references public.members(id) on delete cascade,badge_code text not null references public.caleris_achievement_badges(code) on delete cascade,awarded_at timestamptz not null default now(),source_type text not null default 'system',source_id text,primary key(member_id,badge_code));
insert into public.caleris_achievement_badges(code,title,description,icon,rarity) values('milestone_50','First Milestone','Mencapai 50 XP kumulatif.','target','common'),('xp_800','Rising Star','Mencapai 800 XP kumulatif.','trending-up','rare'),('xp_6400','Elite Progression','Mencapai 6.400 XP kumulatif.','crown','epic'),('community_voice','Community Voice','Berpartisipasi dalam community voting.','vote','common') on conflict(code) do nothing;
insert into public.caleris_milestone_definitions(scope,code,title,description,metric_key,target_value,xp_reward,badge_code) values
('driver','driver_xp_50','First Steps','Mengumpulkan 50 XP kumulatif.','xp_total',50,10,'milestone_50'),('driver','driver_xp_100','Getting Started','Mengumpulkan 100 XP kumulatif.','xp_total',100,15,null),('driver','driver_xp_200','On The Rise','Mengumpulkan 200 XP kumulatif.','xp_total',200,20,null),('driver','driver_xp_400','Consistent','Mengumpulkan 400 XP kumulatif.','xp_total',400,30,null),('driver','driver_xp_800','Rising Star','Mengumpulkan 800 XP kumulatif.','xp_total',800,40,'xp_800'),('driver','driver_xp_1600','Established','Mengumpulkan 1.600 XP kumulatif.','xp_total',1600,60,null),('driver','driver_xp_3200','Front Runner','Mengumpulkan 3.200 XP kumulatif.','xp_total',3200,80,null),('driver','driver_xp_6400','Elite Progression','Mengumpulkan 6.400 XP kumulatif.','xp_total',6400,100,'xp_6400'),('team','team_xp_50','Team Foundation','Milestone tim 50.','team_xp',50,10,null),('team','team_xp_100','Team Momentum','Milestone tim 100.','team_xp',100,15,null),('team','team_xp_200','Team Contender','Milestone tim 200.','team_xp',200,20,null),('team','team_xp_400','Team Excellence','Milestone tim 400.','team_xp',400,30,null) on conflict(code) do nothing;
create or replace function public.caleris_current_member_id() returns uuid language sql stable security definer set search_path=public as $$select member_id from public.profiles where user_id=auth.uid()$$;
create or replace function public.caleris_xp_level(p_total bigint) returns integer language plpgsql immutable as $$declare l integer:=0;t bigint:=50;begin while l<100 and p_total>=t loop l:=l+1;t:=t*2;end loop;return l;end$$;
create or replace function public.caleris_award_xp(p_member_id uuid,p_amount integer,p_source_type text,p_source_id text,p_description text default '') returns boolean language plpgsql security definer set search_path=public as $$declare n integer;begin if auth.role()<>'service_role' and not exists(select 1 from public.site_admins where user_id=auth.uid()) then raise exception 'not_authorized';end if;if p_amount<=0 or p_amount>100000 or nullif(trim(p_source_id),'') is null then raise exception 'invalid_xp_award';end if;insert into public.caleris_xp_ledger(member_id,amount,source_type,source_id,description) values(p_member_id,p_amount,p_source_type,p_source_id,left(coalesce(p_description,''),240)) on conflict(member_id,source_type,source_id) do nothing;get diagnostics n=row_count;if n=1 then insert into public.caleris_activity_feed(actor_member_id,event_type,title,body,metadata) values(p_member_id,'xp_earned','XP diperoleh','+'||p_amount||' XP · '||left(coalesce(p_description,''),160),jsonb_build_object('amount',p_amount,'source_type',p_source_type));end if;return n=1;end$$;
create or replace function public.caleris_cast_community_vote(p_poll_id uuid,p_option_id uuid) returns void language plpgsql security definer set search_path=public as $$declare m uuid:=public.caleris_current_member_id();p public.caleris_community_polls%rowtype;begin if m is null then raise exception 'member_profile_required';end if;select * into p from public.caleris_community_polls where id=p_poll_id for update;if not found or p.status<>'open' or now()<p.starts_at or now()>p.ends_at then raise exception 'poll_not_open';end if;if not exists(select 1 from public.caleris_community_poll_options where id=p_option_id and poll_id=p_poll_id) then raise exception 'invalid_option';end if;insert into public.caleris_community_votes(poll_id,voter_member_id,option_id) values(p_poll_id,m,p_option_id);insert into public.caleris_activity_feed(actor_member_id,event_type,title,body,metadata) values(m,'community_vote','Member berpartisipasi dalam voting','Suara komunitas telah dicatat.',jsonb_build_object('poll_id',p_poll_id));insert into public.caleris_member_badges(member_id,badge_code,source_type,source_id) values(m,'community_voice','community_vote',p_poll_id::text) on conflict do nothing;end$$;
create or replace function public.caleris_save_digital_id(p_theme text,p_accent text,p_tagline text,p_public boolean) returns void language plpgsql security definer set search_path=public as $$declare m uuid:=public.caleris_current_member_id();begin if m is null then raise exception 'member_profile_required';end if;if p_theme not in('classic','premio','zwei','gold') or p_accent !~ '^#[0-9A-Fa-f]{6}$' then raise exception 'invalid_card_style';end if;insert into public.caleris_digital_id_cards(member_id,theme,accent_color,tagline,public_visible) values(m,p_theme,p_accent,left(coalesce(p_tagline,''),80),coalesce(p_public,true)) on conflict(member_id) do update set theme=excluded.theme,accent_color=excluded.accent_color,tagline=excluded.tagline,public_visible=excluded.public_visible,updated_at=now();end$$;
create or replace function public.caleris_update_milestone_progress(p_code text,p_scope text,p_member uuid,p_team uuid,p_value numeric) returns void language plpgsql security definer set search_path=public as $$declare d public.caleris_milestone_definitions%rowtype;begin if auth.role()<>'service_role' and not exists(select 1 from public.site_admins where user_id=auth.uid()) then raise exception 'not_authorized';end if;select * into d from public.caleris_milestone_definitions where code=p_code and active and scope=p_scope;if not found then raise exception 'milestone_not_found';end if;if p_scope='driver' then insert into public.caleris_milestone_progress(milestone_id,scope,member_id,current_value,completed_at) values(d.id,p_scope,p_member,greatest(0,p_value),case when p_value>=d.target_value then now() end) on conflict(milestone_id,member_id) do update set current_value=excluded.current_value,completed_at=coalesce(caleris_milestone_progress.completed_at,excluded.completed_at),updated_at=now();else insert into public.caleris_milestone_progress(milestone_id,scope,team_id,current_value,completed_at) values(d.id,p_scope,p_team,greatest(0,p_value),case when p_value>=d.target_value then now() end) on conflict(milestone_id,team_id) do update set current_value=excluded.current_value,completed_at=coalesce(caleris_milestone_progress.completed_at,excluded.completed_at),updated_at=now();end if;end$$;
alter table public.caleris_xp_ledger enable row level security;alter table public.caleris_milestone_definitions enable row level security;alter table public.caleris_milestone_progress enable row level security;alter table public.caleris_activity_feed enable row level security;alter table public.caleris_community_polls enable row level security;alter table public.caleris_community_poll_options enable row level security;alter table public.caleris_community_votes enable row level security;alter table public.caleris_digital_id_cards enable row level security;alter table public.caleris_season_yearbooks enable row level security;alter table public.caleris_achievement_badges enable row level security;alter table public.caleris_member_badges enable row level security;
create policy "cp xp read" on public.caleris_xp_ledger for select to authenticated using(member_id=public.caleris_current_member_id() or exists(select 1 from public.site_admins where user_id=auth.uid()));
create policy "cp milestone defs read" on public.caleris_milestone_definitions for select to authenticated using(active);
create policy "cp milestone progress read" on public.caleris_milestone_progress for select to authenticated using(member_id=public.caleris_current_member_id() or team_id in(select team_id from public.members where id=public.caleris_current_member_id()));
create policy "cp activity read" on public.caleris_activity_feed for select to authenticated using(visibility='community' or actor_member_id=public.caleris_current_member_id() or team_id in(select team_id from public.members where id=public.caleris_current_member_id()));
create policy "cp polls read" on public.caleris_community_polls for select to authenticated using(status in('open','closed','published') or created_by=auth.uid() or exists(select 1 from public.site_admins where user_id=auth.uid()));
create policy "cp options read" on public.caleris_community_poll_options for select to authenticated using(exists(select 1 from public.caleris_community_polls p where p.id=poll_id and p.status in('open','closed','published')));
create policy "cp votes read" on public.caleris_community_votes for select to authenticated using(true);
create policy "cp digital id read" on public.caleris_digital_id_cards for select to authenticated using(public_visible or member_id=public.caleris_current_member_id());
create policy "cp yearbook read" on public.caleris_season_yearbooks for select to authenticated using(status='published' or exists(select 1 from public.site_admins where user_id=auth.uid()));
create policy "cp badges read" on public.caleris_achievement_badges for select to authenticated using(active);
create policy "cp member badges read" on public.caleris_member_badges for select to authenticated using(true);
revoke all on function public.caleris_award_xp(uuid,integer,text,text,text) from public,anon,authenticated;grant execute on function public.caleris_award_xp(uuid,integer,text,text,text) to service_role,authenticated;
revoke all on function public.caleris_update_milestone_progress(text,text,uuid,uuid,numeric) from public,anon,authenticated;grant execute on function public.caleris_update_milestone_progress(text,text,uuid,uuid,numeric) to service_role,authenticated;
grant execute on function public.caleris_cast_community_vote(uuid,uuid),public.caleris_save_digital_id(text,text,text,boolean) to authenticated;
grant select on public.caleris_xp_ledger,public.caleris_milestone_definitions,public.caleris_milestone_progress,public.caleris_activity_feed,public.caleris_community_polls,public.caleris_community_poll_options,public.caleris_community_votes,public.caleris_digital_id_cards,public.caleris_season_yearbooks,public.caleris_achievement_badges,public.caleris_member_badges to authenticated;